package vn.luma;
import java.net.*;
import java.net.http.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.access.AccessDeniedException;
import vn.luma.business.*;
import vn.luma.web.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"spring.datasource.url=jdbc:postgresql://127.0.0.1:55432/luma_test","app.mail.local-directory=.local/test-mail","app.scheduling.enabled=false"})
class NhanVienIntegrationTest {
 @Autowired QuanLyNguoiDungService employees; @Autowired TaiKhoanService users; @Autowired KhoService stock; @Autowired GiaoNhanService orders; @Autowired CauHinhHeThongService settings;
 @LocalServerPort int port;
 static final String ADMIN="admin@luma.local",PASSWORD="EmployeeDemo!2026";
 @Test @Transactional void employeeCreationRequiresAdminAndStaffCanOperateWithoutEmailVerification(){String email="employee-new-"+UUID.randomUUID()+"@example.test";long id=employees.taoNhanVien(ADMIN,new DangKyYeuCau("Nhân viên mới",email,PASSWORD,PASSWORD));var account=users.hienTai(email);assertThat(account.vaiTro()).isEqualTo("NhanVien");assertThat(account.daXacMinh()).isFalse();assertThat(employees.nhanVien(ADMIN,email,1)).singleElement().satisfies(row->assertThat(((Number)row.get("MaNguoiDung")).longValue()).isEqualTo(id));assertThat(stock.danhSach(email)).isNotNull();employees.luu(ADMIN,id,new NguoiDungYeuCau("NhanVien","BI_KHOA","Khóa thử"));assertThatThrownBy(()->stock.danhSach(email)).isInstanceOf(AccessDeniedException.class);employees.luu(ADMIN,id,new NguoiDungYeuCau("NhanVien","HOAT_DONG","Mở khóa thử"));assertThat(stock.danhSach(email)).isNotNull();assertThatThrownBy(()->employees.taoNhanVien(email,new DangKyYeuCau("Sai quyền","other@example.test",PASSWORD,PASSWORD))).isInstanceOf(AccessDeniedException.class);}
 @Test @Transactional void verifiedStaffCanOperateButCannotManageAccountsAndLockRevokesSessions(){String email="employee-role-"+UUID.randomUUID()+"@example.test";users.seedDemo(email,"Nhân viên kiểm thử","NhanVien",PASSWORD);long id=users.hienTai(email).maNguoiDung();assertThat(stock.danhSach(email)).isNotEmpty();assertThat(orders.donVi(email)).isNotEmpty();assertThatThrownBy(()->employees.danhSach(email,"",1)).isInstanceOf(AccessDeniedException.class);assertThatThrownBy(()->settings.luu(email,null)).isInstanceOf(AccessDeniedException.class);users.ghiPhien(email,"staff-test-session");employees.luu(ADMIN,id,new NguoiDungYeuCau("NhanVien","BI_KHOA","Khóa nhân viên thử"));assertThat(users.phienHopLe(email,"staff-test-session")).isFalse();assertThatThrownBy(()->stock.danhSach(email)).isInstanceOf(AccessDeniedException.class);}
 @Test void realHttpStaffSessionHasRestrictedRoutesAndCannotGrantRoles()throws Exception{String email="employee-http-"+UUID.randomUUID()+"@example.test";users.seedDemo(email,"Nhân viên HTTP","NhanVien",PASSWORD);var client=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();String token=csrf(get(client,"/login").body());var login=client.send(HttpRequest.newBuilder(URI.create(base()+"/login")).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString("username="+enc(email)+"&password="+enc(PASSWORD)+"&_csrf="+enc(token))).build(),HttpResponse.BodyHandlers.ofString());assertThat(login.statusCode()).isEqualTo(302);for(String route:List.of("/quan-tri/san-pham","/quan-tri/model","/quan-tri/don-hang"))assertThat(get(client,route).statusCode()).as(route).isEqualTo(200);for(String route:List.of("/quan-tri/nhan-vien","/quan-tri/nguoi-dung","/quan-tri/bao-cao","/quan-tri/cau-hinh","/quan-tri/hoan-tien"))assertThat(get(client,route).statusCode()).as(route).isEqualTo(403);long id=users.hienTai(email).maNguoiDung();token=csrf(get(client,"/tai-khoan").body());var promote=client.send(HttpRequest.newBuilder(URI.create(base()+"/quan-tri/nguoi-dung/"+id)).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString("vaiTro=QuanTri&trangThai=HOAT_DONG&lyDo=Escalate&_csrf="+enc(token))).build(),HttpResponse.BodyHandlers.ofString());assertThat(promote.statusCode()).isEqualTo(403);assertThat(users.hienTai(email).vaiTro()).isEqualTo("NhanVien");employees.luu(ADMIN,id,new NguoiDungYeuCau("NhanVien","BI_KHOA","Dọn tài khoản HTTP QA"));assertThat(get(client,"/quan-tri/model").statusCode()).isEqualTo(302);}
 String base(){return "http://127.0.0.1:"+port;}String enc(String value){return URLEncoder.encode(value,java.nio.charset.StandardCharsets.UTF_8);}HttpResponse<String> get(HttpClient c,String route)throws Exception{return c.send(HttpRequest.newBuilder(URI.create(base()+route)).GET().build(),HttpResponse.BodyHandlers.ofString());}String csrf(String html){var m=java.util.regex.Pattern.compile("name=\"_csrf\"[^>]*value=\"([^\"]+)\"").matcher(html);assertThat(m.find()).isTrue();return m.group(1);}
}
